with base as (select * from web_events where session_id = 19 and page = '/checkout'), WebEventsStats as (select case when year(event_time) < 2024 then 'before_2024' when year(event_time) = 2024 then '2024' else 'after_2024' end as event_cohort, count(duration_sec) as duration_sec_count, avg(duration_sec) as avg_duration_sec from base group by case when year(event_time) < 2024 then 'before_2024' when year(event_time) = 2024 then '2024' else 'after_2024' end) select event_cohort, duration_sec_count, avg_duration_sec from WebEventsStats order by avg_duration_sec;
